import os,json,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def transform(g):
    h=len(g); w=len(g[0]); out=[row[:] for row in g]
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            c=g[i][j]
            if c==0 or seen[i][j]: continue
            # find bounding box of this color component (4-connectivity)
            stack=[(i,j)]; seen[i][j]=True; cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==c:
                        seen[ny][nx]=True; stack.append((ny,nx))
            ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
            y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
            if y1-y0<2 or x1-x0<2: continue
            ih,iw=y1-y0-1,x1-x0-1
            fill=2 if (ih*iw)%2==0 else 7
            for y in range(y0+1,y1):
                for x in range(x0+1,x1):
                    out[y][x]=fill
    return out

